using System.Globalization;
using System.Windows;
using System.Windows.Input;
using System.Windows.Media;
using CCStats.Core.Library;
namespace CCStats.Desktop.Views;
internal sealed class EventTimelineView:FrameworkElement {
    private readonly TimelineRow[] _events;private readonly string[] _lanes;private readonly DateTime _origin;private readonly double _duration;private double _start,_span;private Point? _drag;private TimelineRow? _hover;
    public event Action<DateTime>? SeekRequested;
    public EventTimelineView(IEnumerable<TimelineRow> events,DateTime origin,double duration){_events=events.OrderBy(e=>e.Timestamp).ToArray();_lanes=_events.Select(e=>Lane(e)).Distinct().ToArray();_origin=origin;_duration=Math.Max(1,duration);_span=_duration;Height=Math.Max(220,_lanes.Length*34+85);MinWidth=500;
        MouseMove+=(_,e)=>{var p=e.GetPosition(this);if(_drag is {} last){_start=Math.Clamp(_start-(p.X-last.X)/Math.Max(1,ActualWidth-190)*_span,0,Math.Max(0,_duration-_span));_drag=p;}else{_hover=Hit(p);ToolTip=_hover==null?null:$"{(_hover.Timestamp-_origin):mm\\:ss\\.fff} · {_hover.Kind}\n{_hover.Actor} → {_hover.Target}\n{_hover.Description}\n双击打开回放";}InvalidateVisual();};MouseLeave+=(_,_)=>{_hover=null;InvalidateVisual();};MouseLeftButtonDown+=(_,e)=>{if(e.ClickCount==2){var hit=Hit(e.GetPosition(this));if(hit!=null)SeekRequested?.Invoke(hit.Timestamp);}else{_drag=e.GetPosition(this);CaptureMouse();}};MouseLeftButtonUp+=(_,_)=>{_drag=null;ReleaseMouseCapture();};LostMouseCapture+=(_,_)=>_drag=null;PreviewMouseWheel+=(_,e)=>{if(!Keyboard.Modifiers.HasFlag(ModifierKeys.Control))return;double fraction=Math.Clamp((e.GetPosition(this).X-165)/Math.Max(1,ActualWidth-190),0,1),anchor=_start+fraction*_span;_span=Math.Clamp(_span*Math.Pow(.8,e.Delta/120d),Math.Min(2,_duration),_duration);_start=Math.Clamp(anchor-fraction*_span,0,Math.Max(0,_duration-_span));e.Handled=true;InvalidateVisual();};}
    private static string Lane(TimelineRow e)=>string.IsNullOrWhiteSpace(e.Actor)?"场地机制":e.Actor;
    private TimelineRow? Hit(Point p){int lane=(int)((p.Y-42)/34);if(lane<0||lane>=_lanes.Length)return null;double seconds=_start+(p.X-165)/Math.Max(1,ActualWidth-190)*_span;return _events.Where(e=>Lane(e)==_lanes[lane]&&Math.Abs((e.Timestamp-_origin).TotalSeconds-seconds)<_span/Math.Max(1,ActualWidth-190)*9).MinBy(e=>Math.Abs((e.Timestamp-_origin).TotalSeconds-seconds));}
    private void Text(DrawingContext dc,string text,Point at,double width=150){var f=new FormattedText(text,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),12,DesktopTheme.Brush("TextBrush"),VisualTreeHelper.GetDpi(this).PixelsPerDip){MaxTextWidth=width,Trimming=TextTrimming.CharacterEllipsis,MaxLineCount=1};dc.DrawText(f,at);}
    protected override void OnRender(DrawingContext dc){base.OnRender(dc);dc.DrawRectangle(DesktopTheme.Brush("SurfaceBrush"),null,new Rect(RenderSize));double width=Math.Max(1,ActualWidth-190);if(_events.Length==0){Text(dc,"此局暂无事件记录",new(20,25),400);return;}for(int i=0;i<_lanes.Length;i++){double y=42+i*34;Text(dc,_lanes[i],new(8,y+3));if(i%2==0)dc.DrawRectangle(DesktopTheme.Brush("AlternateBrush"),null,new Rect(160,y,width+10,30));}for(int i=0;i<=6;i++){double x=165+width*i/6;dc.DrawLine(new Pen(DesktopTheme.Brush("BorderBrush"),.5),new(x,35),new(x,Height-30));Text(dc,TimeSpan.FromSeconds(_start+_span*i/6).ToString(@"mm\:ss"),new(x-12,12),70);}
        foreach(var e in _events){double seconds=(e.Timestamp-_origin).TotalSeconds;if(seconds<_start||seconds>_start+_span)continue;double x=165+(seconds-_start)/_span*width,y=57+Array.IndexOf(_lanes,Lane(e))*34;var brush=e.Kind=="减员"?Brushes.Coral:e.Kind=="地图事件"?Brushes.Gold:Brushes.DeepSkyBlue;dc.DrawEllipse(brush,ReferenceEquals(e,_hover)?new Pen(Brushes.White,2):null,new(x,y),ReferenceEquals(e,_hover)?6:4,6);}
    }
}
